1	package api
2	
3	import (
4		"errors"
5		"net/http"
6	
7		"example.com/tally/internal/auth"
8		"example.com/tally/internal/store"
9		"example.com/tally/internal/webhooks"
10	)
11	
12	func (s *Server) hookError(w http.ResponseWriter, err error) {
13		switch {
14		case errors.Is(err, webhooks.ErrInvalidURL):
15			writeError(w, http.StatusUnprocessableEntity, "invalid_url", err.Error())
16		case errors.Is(err, webhooks.ErrInvalidEvents):
17			writeError(w, http.StatusUnprocessableEntity, "invalid_events", err.Error())
18		default:
19			s.storeError(w, err)
20		}
21	}
22	
23	func (s *Server) listEndpoints(w http.ResponseWriter, r *http.Request, p auth.Principal) {
24		writeJSON(w, http.StatusOK, list{Items: s.store.WebhookEndpoints(p.OrgID)})
25	}
26	
27	// createEndpoint adds an endpoint: {"url": ..., "events": [...]}. The answer includes the signing secret.
28	func (s *Server) createEndpoint(w http.ResponseWriter, r *http.Request, p auth.Principal) {
29		var in struct {
30			URL    string   `json:"url"`
31			Events []string `json:"events"`
32		}
33		if !decode(w, r, &in) {
34			return
35		}
36		if err := s.hooks.CheckURL(r.Context(), in.URL); err != nil {
37			s.hookError(w, err)
38			return
39		}
40		if err := webhooks.CheckEvents(in.Events); err != nil {
41			s.hookError(w, err)
42			return
43		}
44		ep, err := s.store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: p.OrgID, URL: in.URL, Events: in.Events, Secret: webhooks.NewSecret(), Enabled: true}, s.clock.Now())
45		if err != nil {
46			s.storeError(w, err)
47			return
48		}
49		writeJSON(w, http.StatusCreated, ep)
50	}
51	
52	func (s *Server) getEndpoint(w http.ResponseWriter, r *http.Request, p auth.Principal) {
53		ep, ok := s.store.WebhookEndpoint(p.OrgID, r.PathValue("id"))
54		if !ok {
55			writeError(w, http.StatusNotFound, "not_found", "no such webhook endpoint")
56			return
57		}
58		writeJSON(w, http.StatusOK, ep)
59	}
60	
61	func (s *Server) updateEndpoint(w http.ResponseWriter, r *http.Request, p auth.Principal) {
62		var in struct {
63			URL     *string   `json:"url"`
64			Events  *[]string `json:"events"`
65			Enabled *bool     `json:"enabled"`
66		}
67		if !decode(w, r, &in) {
68			return
69		}
70		if in.URL != nil {
71			if err := s.hooks.CheckURL(r.Context(), *in.URL); err != nil {
72				s.hookError(w, err)
73				return
74			}
75		}
76		if in.Events != nil {
77			if err := webhooks.CheckEvents(*in.Events); err != nil {
78				s.hookError(w, err)
79				return
80			}
81		}
82		ep, err := s.store.UpdateWebhookEndpoint(p.OrgID, r.PathValue("id"), func(ep *store.WebhookEndpoint) error {
83			if in.URL != nil {
84				ep.URL = *in.URL
85			}
86			if in.Events != nil {
87				ep.Events = *in.Events
88			}
89			if in.Enabled != nil {
90				ep.Enabled = *in.Enabled
91				if ep.Enabled {
92					ep.DisabledReason = ""
93				}
94			}
95			return nil
96		})
97		if err != nil {
98			s.storeError(w, err)
99			return
100		}
101		writeJSON(w, http.StatusOK, ep)
102	}
103	
104	func (s *Server) deleteEndpoint(w http.ResponseWriter, r *http.Request, p auth.Principal) {
105		if err := s.store.DeleteWebhookEndpoint(r.PathValue("id")); err != nil {
106			s.storeError(w, err)
107			return
108		}
109		w.WriteHeader(http.StatusNoContent)
110	}
111	
112	func (s *Server) listDeliveries(w http.ResponseWriter, r *http.Request, p auth.Principal) {
113		ep, ok := s.store.WebhookEndpoint(p.OrgID, r.PathValue("id"))
114		if !ok {
115			writeError(w, http.StatusNotFound, "not_found", "no such webhook endpoint")
116			return
117		}
118		writeJSON(w, http.StatusOK, list{Items: s.store.Deliveries(p.OrgID, ep.ID)})
119	}
120	
121	func eventKey(e store.Event) cursor { return cursor{T: e.CreatedAt, ID: e.ID} }
122	
123	func (s *Server) listEvents(w http.ResponseWriter, r *http.Request, p auth.Principal) {
124		pg, ok := parsePage(w, r)
125		if !ok {
126			return
127		}
128		items, next := pageOf(s.store.Events(p.OrgID, r.URL.Query().Get("type")), eventKey, pg)
129		writeJSON(w, http.StatusOK, list{Items: items, NextCursor: next})
130	}
131	
132	func (s *Server) getEvent(w http.ResponseWriter, r *http.Request, p auth.Principal) {
133		e, ok := s.store.Event(p.OrgID, r.PathValue("id"))
134		if !ok {
135			writeError(w, http.StatusNotFound, "not_found", "no such event")
136			return
137		}
138		writeJSON(w, http.StatusOK, e)
139	}
