// notPublic are the address ranges a webhook endpoint's host must not be in: "this network", private, carrier-grade NAT,
// loopback, link-local, multicast, broadcast and unspecified addresses.
var notPublic = []netip.Prefix{
	netip.MustParsePrefix("0.0.0.0/8"),
	netip.MustParsePrefix("10.0.0.0/8"),
	netip.MustParsePrefix("100.64.0.0/10"),
	netip.MustParsePrefix("127.0.0.0/8"),
	netip.MustParsePrefix("169.254.0.0/16"),
	netip.MustParsePrefix("172.16.0.0/12"),
	netip.MustParsePrefix("192.168.0.0/16"),
	netip.MustParsePrefix("224.0.0.0/4"),
	netip.MustParsePrefix("255.255.255.255/32"),
	netip.MustParsePrefix("::/128"),
	netip.MustParsePrefix("::1/128"),
	netip.MustParsePrefix("fc00::/7"),
	netip.MustParsePrefix("fe80::/10"),
	netip.MustParsePrefix("ff00::/8"),
}

// isPublic reports whether a is a public address. An IPv4-mapped IPv6 address is judged as the IPv4 address it holds. An
// invalid address is not public.
func isPublic(a netip.Addr) bool {
	if !a.IsValid() {
		return false
	}
	a = a.Unmap().WithZone("")
	for _, p := range notPublic {
		if p.Contains(a) {
			return false
		}
	}
	return true
}

// hostAddrs returns the addresses a URL host stands for: the host itself when it is an IP address, else every address the
// host resolves to. An address the resolver returns that is not a valid IP is returned invalid, so that it is not public.
func (s *Service) hostAddrs(ctx context.Context, host string) ([]netip.Addr, error) {
	if a, err := netip.ParseAddr(host); err == nil {
		return []netip.Addr{a}, nil
	}
	ips, err := s.resolver.LookupIPAddr(ctx, host)
	if err != nil || len(ips) == 0 {
		return nil, fmt.Errorf("the host %q does not resolve", host)
	}
	out := make([]netip.Addr, 0, len(ips))
	for _, ip := range ips {
		a, _ := netip.AddrFromSlice(ip.IP)
		out = append(out, a)
	}
	return out, nil
}

// CheckURL checks a webhook URL before it is saved: an https URL with a host and no user name or password, whose host is,
// or resolves only to, public addresses.
func (s *Service) CheckURL(ctx context.Context, raw string) error {
	u, err := url.Parse(raw)
	host := u.Hostname()
	if err != nil || u.Scheme != "https" || host == "" || u.User != nil {
		return fmt.Errorf("%w: use an absolute https URL without a user name or password", ErrInvalidURL)
	}
	addrs, err := s.hostAddrs(ctx, host)
	if err != nil {
		return fmt.Errorf("%w: %w", ErrInvalidURL, err)
	}
	for _, a := range addrs {
		if !isPublic(a) {
			return fmt.Errorf("%w: the host %q is not public", ErrInvalidURL, host)
		}
	}
	return nil
}

// errNotPublic is the error of a delivery that is not sent because the endpoint's host is not public.
var errNotPublic = errors.New("the endpoint's address is not public")

