func TestDeliveryRechecksAddress(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	ep, _ := e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/", Events: []string{"*"}, Secret: "whsec_a", Enabled: true}, e.Clock.Now())

	// The host now resolves to the metadata address: nothing is sent, the attempt fails, the endpoint is unchanged.
	e.DNS.Set("hooks.acme.example", "169.254.169.254")
	_ = e.Webhooks.Publish(ctx, e.Acme.ID, "customer.created", map[string]string{"id": "cus_1"})
	if n, err := e.Webhooks.RunDue(ctx); err != nil || n != 1 {
		t.Fatalf("RunDue = %d, %v", n, err)
	}
	if reqs := e.HTTP.Requests(); len(reqs) != 0 {
		t.Fatalf("a request was sent to a non-public address: %+v", reqs)
	}
	ds := e.Store.Deliveries(e.Acme.ID, ep.ID)
	if len(ds) != 1 || ds[0].Status != store.DeliveryFailed || !strings.Contains(ds[0].Error, "not public") {
		t.Fatalf("deliveries = %+v", ds)
	}
	if got, _ := e.Store.WebhookEndpoint(e.Acme.ID, ep.ID); got.URL != ep.URL || !got.Enabled {
		t.Fatalf("endpoint changed: %+v", got)
	}

	// The host is public again: the next delivery is sent.
	e.DNS.Set("hooks.acme.example", "93.184.216.34")
	_ = e.Webhooks.Publish(ctx, e.Acme.ID, "customer.created", map[string]string{"id": "cus_2"})
	if n, err := e.Webhooks.RunDue(ctx); err != nil || n != 1 {
		t.Fatalf("RunDue = %d, %v", n, err)
	}
	if reqs := e.HTTP.Requests(); len(reqs) != 1 {
		t.Fatalf("requests = %+v", reqs)
	}
}

